void analyze(const int *a, int n, int *psum, int *pmax, int *pmin, int *ppos)
{
    const int *p;

    *psum = 0;
    *ppos = 0;
    *pmax = *a;
    *pmin = *a;

    for (p = a; p < a + n; p++) {
        *psum += *p;
        if (*p > *pmax)
            *pmax = *p;
        if (*p < *pmin)
            *pmin = *p;
        if (*p > 0)
            (*ppos)++;
    }
}

