    return 0;
}

#include <stdio.h>
#include <ctype.h>

#define MAXLEN 105

int my_strlen(const char *s)
{
    const char *p = s;

    while (*p != '\0')
        p++;
    return (int)(p - s);
}

void my_strcpy(char *dst, const char *src)
{
    while (*src != '\0') {
        *dst = *src;
        dst++;
        src++;
    }
    *dst = '\0';
}

int main(void)
{
    char s[MAXLEN];
    char copy[MAXLEN];
    const char *p;
    int upper = 0, lower = 0, digit = 0;

    if (scanf("%100s", s) != 1)
        return 0;

    my_strcpy(copy, s);

    for (p = s; *p != '\0'; p++) {
        if (isupper((unsigned char)*p))
            upper++;
        else if (islower((unsigned char)*p))
            lower++;
        else if (isdigit((unsigned char)*p))
            digit++;
    }

    printf("%d\n", my_strlen(s));
    printf("%s\n", copy);
    printf("%d %d %d\n", upper, lower, digit);
    return 0;
}

#include <stdio.h>

#define MAXLEN 105

int my_strcmp(const char *s1, const char *s2)
{
    const unsigned char *p = (const unsigned char *)s1;
    const unsigned char *q = (const unsigned char *)s2;

    while (*p != '\0' && *p == *q) {
        p++;
        q++;
    }
    if (*p == *q)
        return 0;
    return (*p < *q) ? -1 : 1;
}

int first_diff(const char *s1, const char *s2)
{
    const char *p = s1;
    const char *q = s2;

    while (*p != '\0' && *p == *q) {
        p++;
        q++;
    }
    if (*p == *q)
        return -1;
    return (int)(p - s1);
}

int main(void)
{
    char s1[MAXLEN], s2[MAXLEN];

    if (scanf("%100s", s1) != 1)
        return 0;
    if (scanf("%100s", s2) != 1)
        return 0;

    printf("%d\n", my_strcmp(s1, s2));
    printf("%d\n", first_diff(s1, s2));
    return 0;
}

#include <stdio.h>

#define MAXLEN 1005
#define MAXW 505

int split(char *s, char *words[])
{
    int cnt = 0;
    char *p = s;

    while (*p != '\0') {
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')
            p++;
        if (*p == '\0')
            break;
        if (cnt < MAXW)
            words[cnt++] = p;
        while (*p != '\0' && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r')
            p++;
        if (*p != '\0') {
            *p = '\0';
            p++;
        }
    }
    return cnt;
}

int main(void)
{
    char text[MAXLEN];
    char *words[MAXW];
    int cnt, i;

    if (fgets(text, sizeof text, stdin) == NULL)
        return 0;

    cnt = split(text, words);

    printf("%d\n", cnt);
    for (i = 0; i < cnt; i++)
        printf("%s\n", words[i]);
    return 0;
}

#include <stdio.h>

#define MAXLEN 510

void strip_newline(char *s)
{
    char *p = s;

    while (*p != '\0' && *p != '\n' && *p != '\r')
        p++;
    *p = '\0';
}

char *locatesubstr(char *str1, char *str2)
{
    char *p;
    char *t;

    if (*str2 == '\0')
        return str1;

    for (p = str1; *p != '\0'; p++) {
        char *s = p;

        t = str2;
        while (*t != '\0' && *s == *t) {
            s++;
            t++;
        }
        if (*t == '\0')
            return p;
    }
    return NULL;
}

int main(void)
{
    char str1[MAXLEN];
    char str2[MAXLEN];
    char *p;

    if (fgets(str1, sizeof str1, stdin) == NULL)
        return 0;
    if (fgets(str2, sizeof str2, stdin) == NULL)
        return 0;
    strip_newline(str1);
    strip_newline(str2);

    p = locatesubstr(str1, str2);
    if (p == NULL) {
        printf("NULL!\n");
    } else {
        printf("%d\n", (int)(p - str1));
        printf("%s\n", p);
    }
    return 0;
}

#include <stdio.h>

#define MAXLEN 205
#define MAXSET 25

int delchars(char *str, const char *set)
{
    char *dst = str;
    char *src;
    int removed = 0;

    for (src = str; *src != '\0'; src++) {
        const char *q = set;
        int hit = 0;

        while (*q != '\0') {
            if (*q == *src) {
                hit = 1;
                break;
            }
            q++;
        }
        if (hit)
            removed++;
        else
            *dst++ = *src;
    }
    *dst = '\0';
    return removed;
}

int main(void)
{
    char str[MAXLEN];
    char set[MAXSET];
    int removed;

    if (scanf("%200s", str) != 1)
        return 0;
    if (scanf("%20s", set) != 1)
        return 0;

    removed = delchars(str, set);

    printf("%s\n", str);
    printf("%d\n", removed);
    return 0;
}

