#include <stdio.h>

#define MAXN 105
#define MAXLEN 105

int my_len(const char *s)
{
    const char *p = s;

    while (*p != '\0')
        p++;
    return (int)(p - s);
}

int my_cmp(const char *s1, const char *s2)
{
    const char *p = s1;
    const char *q = s2;

    while (*p != '\0' && *p == *q) {
        p++;
        q++;
    }
    if (*p == *q)
        return 0;
    return ((unsigned char)*p < (unsigned char)*q) ? -1 : 1;
}

int main(void)
{
    int n, i, j;
    char store[MAXN][MAXLEN];
    char *p[MAXN];

    if (scanf("%d", &n) != 1 || n <= 0)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%100s", store[i]) != 1)
            return 0;
        p[i] = store[i];
    }

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            int la = my_len(p[j]);
            int lb = my_len(p[j + 1]);
            int need = 0;

            if (la > lb)
                need = 1;
            else if (la == lb && my_cmp(p[j], p[j + 1]) > 0)
                need = 1;

            if (need) {
                char *t = p[j];

                p[j] = p[j + 1];
                p[j + 1] = t;
            }
        }
    }

    for (i = 0; i < n; i++)
        printf("%s\n", p[i]);
    return 0;
}

