    int cnt[128];
    int c, best = 0, bestc = -1, found = 0;

    for (c = 0; c < 128; c++)
        cnt[c] = 0;

    if (fgets(text, sizeof text, stdin) == NULL)
        return 0;

    for (p = text; *p != '\0'; p++) {
        unsigned char u = (unsigned char)*p;

        if ((u >= 'A' && u <= 'Z') || (u >= 'a' && u <= 'z'))
            cnt[u]++;
    }

    for (c = 0; c < 128; c++) {
        if (cnt[c] > 0) {
            found = 1;
            if (cnt[c] > best) {
                best = cnt[c];
                bestc = c;
            }
        }
    }

    if (!found) {
        printf("none\n");
    } else {
        printf("%c\n", bestc);
        printf("%d\n", best);
    }
    return 0;
}

