#define MAXLEN 210

int my_strcmp(const char *s1, const char *s2)
{
    const unsigned char *p = (const unsigned char *)s1;
    const unsigned char *q = (const unsigned char *)s2;

    while (*p != '\0' && *p == *q) {
        p++;
        q++;
    }
    if (*p == *q)
        return 0;
    return (*p < *q) ? -1 : 1;
}

int cmp_asc(const char *a, const char *b)
{
    return my_strcmp(a, b);
}

int cmp_desc(const char *a, const char *b)
{
    return -my_strcmp(a, b);
}

void sort(char **a, int n, int (*cmp)(const char *, const char *))
{
    int i, j;

    for (i = 0; i < n - 1; i++) {
        for (j = 0; j < n - 1 - i; j++) {
            if (cmp(a[j], a[j + 1]) > 0) {
                char *t = a[j];

                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
}

